<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Order extends Model { use HasFactory; protected $fillable = ['user_id', 'stall_id', 'pickup_time', 'total_amount', 'status', 'payment_status']; protected$casts = ['total_amount' => 'decimal:2']; public function user() { return $this->belongsTo(User::class); } public function stall() { return$this->belongsTo(Stall::class); } public function orderItems() { return $this->hasMany(OrderItem::class); } public function foodItems() { return$this->belongsToMany(FoodItem::class, 'order_items')->withPivot('quantity', 'unit_price')->withTimestamps(); } }